package org.audiveris.omr.score;
import org.audiveris.omr.sheet.Book;import org.audiveris.omr.sheet.Staff;import org.audiveris.omr.sheet.rhythm.Measure;import org.audiveris.omr.sig.inter.KeyInter;
import org.audiveris.proxymusic.ScorePartwise;import org.audiveris.proxymusic.ScorePart;
import java.nio.file.*;import java.util.*;import java.awt.Rectangle;
public class SourceKeyRecovery331 {
 record Proof(int unit,int system,Staff staff,Staff donor,KeyInter key,int fifths,Rectangle bounds,String sha){}
 static final IdentityHashMap<Staff,Proof> registry=new IdentityHashMap<>();static final ArrayList<String> ledger=new ArrayList<>();
 static String sha(Path p)throws Exception{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(p)));}
 static void require(boolean b,String s){if(!b)throw new IllegalArgumentException(s);}
 public static void mark(Measure measure,ScorePartwise.Part part,ScorePartwise.Part.Measure dest){for(var st:measure.getPart().getStaves()){var p=registry.get(st);if(p==null)continue;ledger.add(String.join("\t",""+p.unit(),""+p.system(),""+st.getId(),""+p.donor().getId(),""+p.key().getId(),""+p.fifths(),p.sha(),((ScorePart)part.getId()).getId(),dest.getNumber(),""+(st.getIndexInPart()+1),""+(measure==measure.getPart().getMeasures().getFirst())));}}
 public static void main(String[] a){try{run(a);System.exit(0);}catch(Throwable t){t.printStackTrace();System.exit(1);}}
 static void run(String[] a)throws Exception{
 ((ch.qos.logback.classic.Logger)org.slf4j.LoggerFactory.getLogger(org.slf4j.Logger.ROOT_LOGGER_NAME)).setLevel(ch.qos.logback.classic.Level.WARN);
 Path nativePath=Path.of(a[0]),source=Path.of(a[2]),out=Path.of(a[4]);require(sha(nativePath).equals(a[1]),"native SHA changed");String hint=a[6];if(!hint.isBlank()){var field=PartCollation.class.getDeclaredField("constants");field.setAccessible(true);var c=field.get(null);var hf=c.getClass().getDeclaredField("partsHint");hf.setAccessible(true);((org.audiveris.omr.constant.Constant.String)hf.get(c)).setStringValue(hint);}
 var book=Book.loadBook(nativePath);require(book!=null,"load");var proofs=new ArrayList<Proof>();var seen=new HashSet<String>();
 for(var line:Files.readAllLines(Path.of(a[3]))){if(line.isBlank())continue;var f=line.split("\t");require(f.length==11,"plan format");int unit=Integer.parseInt(f[0]),system=Integer.parseInt(f[1]);var sys=book.getStub(unit).getSheet().getSystems().stream().filter(s->s.getId()==system).findFirst().orElseThrow();var target=sys.getStaves().stream().filter(s->s.getId()==Integer.parseInt(f[2])).findFirst().orElseThrow();var donor=sys.getStaves().stream().filter(s->s.getId()==Integer.parseInt(f[3])).findFirst().orElseThrow();require(seen.add(unit+":"+system+":"+target.getId()),"duplicate target");require(target!=donor&&target.getHeader().key==null,"target key already present");var key=donor.getHeader().key;require(key!=null&&key.getId()==Integer.parseInt(f[4])&&key.getFifths()==Integer.parseInt(f[5]),"donor key identity mismatch");require(key.getFifths()!=0&&Math.abs(key.getFifths())<=7&&key.getMembers().size()==Math.abs(key.getFifths()),"source donor not complete key");require(sys.getSig().vertexSet().stream().noneMatch(v->v instanceof KeyInter&&v.getStaff()==target),"orphan/conflicting target key");require(sha(source.resolve(String.format("unit-%03d.png",unit))).equals(f[10]),"source PNG changed");var b=new Rectangle(Integer.parseInt(f[6]),Integer.parseInt(f[7]),Integer.parseInt(f[8]),Integer.parseInt(f[9]));require(b.width>0&&b.height>0&&b.x>=target.getAbscissa(org.audiveris.omr.util.HorizontalSide.LEFT),"source key geometry invalid");proofs.add(new Proof(unit,system,target,donor,key,Integer.parseInt(f[5]),b,f[10]));}
 for(var p:proofs){registry.put(p.staff(),p);if(a[5].equals("apply")){var key=p.key().replicate(p.staff());key.setBounds(p.bounds());key.setFromTemplate(true);p.staff().getSystem().getSig().addVertex(key);p.staff().getHeader().key=key;p.staff().getPart().getMeasures().getFirst().addInter(key);}else require(a[5].equals("control"),"mode");}
 if(!hint.isBlank())for(var score:book.getScores()){score.setLogicalsLocked(false);score.setLogicalParts(null);new ScoreReduction(score).reduce(book.getValidStubs());}
 book.setExportPathSansExt(out.resolve("result"));require(book.export(book.getValidStubs(),book.getScores()),"export");var rows=new ArrayList<String>();rows.add("unit\tsystem\tstaff\tdonor_staff\tdonor_key\tfifths\tsource_sha256\tpart\tmeasure\tstaff_number\theader");rows.addAll(ledger);Files.write(out.resolve("key-ledger.tsv"),rows);require(sha(nativePath).equals(a[1]),"source archive changed");System.out.println("SOURCE_KEY_EXPORT_OK "+a[5]+" "+proofs.size());
 }
}
